<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {api,getSession,clearSession} from '../../services/api'
import {useRouter} from 'vue-router'
import '../../styles/auth.css'
import Navbar from '../../components/admin/Navbar.vue'
import Sidebar from '../../components/admin/Sidebar.vue'
import '../../styles/admin/dashboard.css'
const cursosAsignados=ref([]);const router=useRouter(),curso=ref(''),alumnos=ref([]),seleccion=ref([]),solicitudes=ref([]),elegidas=ref([]),error=ref(''),aviso=ref(''),busqueda=ref(''),aulaAbierta=ref(false),sesionAula=ref(null),cargandoAula=ref(false);let timer
const filtrados=computed(()=>alumnos.value.filter(a=>a.nombre.toLowerCase().includes(busqueda.value.toLowerCase())))
async function cargar(){if(!curso.value){alumnos.value=[];solicitudes.value=[];return}try{const [a,s]=await Promise.all([api('/docente/estudiantes?curso='+curso.value),api('/docente/solicitudes?curso='+curso.value)]);alumnos.value=a;seleccion.value=a.filter(x=>x.habilitado).map(x=>x.id);solicitudes.value=s}catch(e){error.value=e.message}}
async function actualizarSolicitudes(){if(!curso.value)return;try{const [s,a]=await Promise.all([api('/docente/solicitudes?curso='+curso.value),api('/docente/aula/estado?curso='+curso.value)]);solicitudes.value=s;aulaAbierta.value=a.abierta;sesionAula.value=a.sesion}catch(e){error.value=e.message}}
async function cambiarCurso(){await cargar();await actualizarSolicitudes()}
async function cambiarAula(abrir){cargandoAula.value=true;error.value='';try{const r=await api('/docente/aula/'+(abrir?'abrir':'cerrar'),{method:'POST',body:JSON.stringify({curso:curso.value})});aulaAbierta.value=r.abierta;sesionAula.value=r.id?{id:r.id}:null;aviso.value=abrir?'Aula abierta. Los estudiantes pueden solicitar acceso.':'Clase finalizada. Las sesiones de este paralelo fueron cerradas.';if(!abrir){solicitudes.value=[];elegidas.value=[]}}catch(e){error.value=e.message}finally{cargandoAula.value=false}}
async function guardar(){try{await api('/docente/habilitaciones',{method:'PUT',body:JSON.stringify({curso:curso.value,ids:seleccion.value})});aviso.value='Habilitaciones guardadas correctamente.';await cargar()}catch(e){error.value=e.message}}
async function resolver(aprobar){try{await api('/docente/solicitudes/resolver',{method:'POST',body:JSON.stringify({ids:elegidas.value,aprobar})});elegidas.value=[];aviso.value=aprobar?'Solicitudes autorizadas.':'Solicitudes rechazadas.';await cargar()}catch(e){error.value=e.message}}
function salir(){clearSession();router.push('/login')}
onMounted(async()=>{try{cursosAsignados.value=await api('/docente/cursos');curso.value=cursosAsignados.value[0]||'';if(curso.value){await cargar();await actualizarSolicitudes()}}catch(e){error.value=e.message}timer=setInterval(()=>{if(!document.hidden && curso.value)actualizarSolicitudes()},5000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><Navbar/><div class="docente-layout-compartido"><Sidebar/><main class="gato-content"><h1 class="h3">Mis estudiantes</h1><p>Administra el acceso de tus estudiantes al aula de computación y revisa las solicitudes pendientes.</p><div v-if="!cursosAsignados.length" class="alert alert-warning">Todavía no tienes paralelos asignados. Solicita al administrador que te asigne los cuatro cursos.</div><div v-if="error" class="gato-error">{{error}}</div><div v-if="aviso" class="gato-ok">{{aviso}}</div><div class="row g-3"><div class="col-lg-6"><section class="gato-tile"><h2 class="h5">Habilitar estudiantes</h2><label class="form-label">Curso</label><select v-model="curso" @change="cambiarCurso" class="form-select mb-3"><option v-for="c in cursosAsignados" :key="c" :value="c">3° {{c.slice(1)}}</option></select><p>{{seleccion.length}} de {{alumnos.length}} habilitados</p><div class="alert" :class="aulaAbierta?'alert-success':'alert-secondary'">{{aulaAbierta?'Aula abierta: los estudiantes pueden solicitar acceso.':'Aula cerrada: no se admiten nuevos ingresos.'}}</div><div class="d-flex gap-2 mb-3"><button class="btn btn-success" :disabled="aulaAbierta||cargandoAula||!curso" @click="cambiarAula(true)">Abrir aula</button><button class="btn btn-outline-danger" :disabled="!aulaAbierta||cargandoAula" @click="cambiarAula(false)">Cerrar clase y sesiones</button></div><div class="d-flex gap-2 flex-wrap mb-3"><button class="btn btn-outline-success btn-sm" @click="seleccion=alumnos.map(a=>a.id)">Habilitar todos</button><button class="btn btn-outline-danger btn-sm" @click="seleccion=[]">Deshabilitar todos</button></div><input v-model="busqueda" class="form-control mb-2" placeholder="Buscar estudiante"><div style="max-height:320px;overflow:auto"><label v-for="a in filtrados" :key="a.id" class="d-flex align-items-center gap-2 border-bottom py-2"><input v-model="seleccion" type="checkbox" :value="a.id"><span>{{a.nombre}}</span></label></div><button class="btn btn-primary w-100 mt-3" @click="guardar">Guardar habilitaciones</button></section></div><div class="col-lg-6"><section class="gato-tile"><h2 class="h5">Solicitudes pendientes</h2><p class="small text-muted">Comprueba presencialmente la identidad del estudiante antes de aprobar su solicitud.</p><div v-if="!solicitudes.length" class="text-muted">No hay solicitudes pendientes.</div><label v-for="s in solicitudes" :key="s.id" class="d-flex gap-2 align-items-center border-bottom py-3"><input v-model="elegidas" type="checkbox" :value="s.id"><span><strong>{{s.nombre}}</strong><br><small>Paralelo {{s.curso}} · Verifica presencialmente quién utiliza la computadora</small></span></label><div class="d-flex gap-2 mt-3"><button class="btn btn-success" :disabled="!elegidas.length" @click="resolver(true)">Aprobar seleccionados</button><button class="btn btn-outline-danger" :disabled="!elegidas.length" @click="resolver(false)">Rechazar</button></div></section></div></div></main></div></template>
<style scoped>.docente-layout-compartido{display:flex;min-height:calc(100vh - 82px);background:#f4f8ff}.docente-layout-compartido :deep(.sidebar){flex:0 0 250px}.docente-layout-compartido .gato-content{flex:1;min-width:0;max-width:1200px}@media(max-width:760px){.docente-layout-compartido{flex-direction:column}.docente-layout-compartido :deep(.sidebar){flex:initial;min-height:auto;width:100%}}</style>
